import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

const ManageParticipants = () => {
    const [participants, setParticipants] = useState([]);
    const [newParticipantName, setNewParticipantName] = useState('');
    const [newParticipantTeam, setNewParticipantTeam] = useState('');
    const navigate = useNavigate();

    // Fetch participants from backend
    const fetchParticipants = () => {
        // This should be an API call
        const mockParticipants = [
            { id: 1, name: 'Candidate 1', team: 'Team A' },
            { id: 2, name: 'Candidate 2', team: 'Team A' },
            { id: 3, name: 'Candidate 3', team: 'Team B' },
        ];
        setParticipants(mockParticipants);
    };

    useEffect(() => {
        fetchParticipants();
    }, []);

    const handleAddParticipant = (e) => {
        e.preventDefault();
        if (!newParticipantName || !newParticipantTeam) return;
        const newParticipant = {
            id: Date.now(), // temporary id
            name: newParticipantName,
            team: newParticipantTeam,
        };
        setParticipants([...participants, newParticipant]);
        setNewParticipantName('');
        setNewParticipantTeam('');
        // Here you would also make a POST request to your backend
    };

    const handleDeleteParticipant = (id) => {
        setParticipants(participants.filter(p => p.id !== id));
        // Here you would also make a DELETE request to your backend
    };

    const handleNext = () => {
        // Save participants list if needed, then navigate
        navigate('/manage-questions');
    };

    return (
        <div className="manage-participants-container">
            <h2>Gérer les Participants</h2>
            
            <div className="participant-list">
                {participants.map(p => (
                    <div key={p.id} className="participant-item">
                        <span>{p.name} ({p.team})</span>
                        <button onClick={() => handleDeleteParticipant(p.id)}>Supprimer</button>
                    </div>
                ))}
            </div>

            <form onSubmit={handleAddParticipant} className="add-participant-form">
                <h3>Ajouter un nouveau participant</h3>
                <input 
                    type="text" 
                    placeholder="Nom du participant" 
                    value={newParticipantName} 
                    onChange={(e) => setNewParticipantName(e.target.value)} 
                    required 
                />
                <input 
                    type="text" 
                    placeholder="Équipe" 
                    value={newParticipantTeam} 
                    onChange={(e) => setNewParticipantTeam(e.target.value)} 
                    required 
                />
                <button type="submit">Ajouter</button>
            </form>

            <button onClick={handleNext} className="next-btn">Suivant</button>
        </div>
    );
};

export default ManageParticipants;
